    "descripcion": "🔹 ANTES DE LA ENTREVISTA (before the interview):\n• Investiga sobre la empresa: su sector, productos y cultura corporativa.\n• Revisa tu currículum y prepara ejemplos concretos de tus experiencias.\n• Practica respuestas a preguntas frecuentes en voz alta.\n• Prepara preguntas para el entrevistador sobre el puesto y el equipo.\n• Cuida tu apariencia: viste de forma profesional y adecuada al sector.\n• Llega puntual o unos minutos antes; la puntualidad es fundamental.\n\n🔹 DURANTE LA ENTREVISTA (during the interview):\n• Saluda con cortesía: «Buenos días, encantado/a de conocerle».\n• Mantén contacto visual y una postura erguida.\n• Escucha con atención y responde de forma clara y concisa.\n• Evita hablar mal de empleos anteriores.\n• Muestra entusiasmo por el puesto y la empresa.\n• Al final, agradece la oportunidad: «Muchas gracias por su tiempo».\n\n🔹 DESPUÉS DE LA ENTREVISTA (after the interview):\n• Envía un correo electrónico de agradecimiento en las 24 horas siguientes.\n• Reflexiona sobre cómo te fue para mejorar en futuras ocasiones.\n\n📌 NOTA IMPORTANTE: En España y Latinoamérica, se valora mucho la cercanía y la amabilidad, pero sin perder el respeto. Usa «usted» hasta que te inviten a tutear.\n\n❌ ERROR COMÚN: Los sinohablantes suelen traducir literalmente «请多关照» como «Por favor, cuídame mucho», lo cual suena extraño. En su lugar, di «Es un placer formar parte de este equipo» o «Espero poder aportar mi experiencia».",
    "descripcionChino": "🔹 面试前：\n• 调查公司：行业、产品和企业文化。\n• 复习简历，准备具体经历的例子。\n• 大声练习常见问题的回答。\n• 准备向面试官提问的问题，关于职位和团队。\n• 注意外表：穿着专业且符合行业。\n• 准时或提前几分钟到达；守时至关重要。\n\n🔹 面试中：\n• 礼貌问候：「Buenos días, encantado/a de conocerle」。\n• 保持眼神交流和端正姿态。\n• 认真倾听，清晰简洁地回答。\n• 避免说前雇主的坏话。\n• 表现出对职位和公司的热情。\n• 最后感谢机会：「Muchas gracias por su tiempo」。\n\n🔹 面试后：\n• 24小时内发送感谢邮件。\n• 反思表现，以便未来改进。\n\n📌 重要提示：在西班牙和拉美，人们很看重亲切和友善，但不要失去尊重。在对方邀请你使用「你」之前，请用「您」。\n\n❌ 常见错误：中文母语者常把「请多关照」直译为「Por favor, cuídame mucho」，听起来很奇怪。应该说「Es un placer formar parte de este equipo」或「Espero poder aportar mi experiencia」。",
