    "descripcion": "🔹 HABLA DE TI MISMO (tell me about yourself):\n• «Soy una persona responsable y me adapto fácilmente al trabajo en equipo».\n• «Tengo tres años de experiencia en atención al cliente».\n• «Me considero proactivo y con ganas de aprender».\n• «Disfruto resolviendo problemas y aportando soluciones».\n• «Mi mayor fortaleza es la comunicación eficaz».\n\n🔹 FORTALEZAS Y DEBILIDADES (strengths and weaknesses):\n• Fortaleza: «Soy organizado y cumplo los plazos».\n• Fortaleza: «Tengo facilidad para los idiomas».\n• Debilidad: «A veces soy demasiado perfeccionista, pero estoy aprendiendo a priorizar».\n• Debilidad: «Me cuesta delegar, pero he mejorado con la práctica».\n• Consejo: menciona una debilidad real y cómo la estás superando.\n\n🔹 ¿POR QUÉ QUIERES TRABAJAR AQUÍ? (why do you want to work here?):\n• «Admiro la trayectoria de la empresa y quiero contribuir a su crecimiento».\n• «Me identifico con los valores de sostenibilidad y trabajo en equipo».\n• «Busco un desafío profesional en un entorno internacional».\n• «Su enfoque en la innovación coincide con mi forma de trabajar».\n• «Creo que puedo aportar mi experiencia en marketing digital».\n\n📌 NOTA IMPORTANTE: Evita respuestas memorizadas; sé natural y personaliza según la empresa. Los entrevistadores valoran la autenticidad.\n\n❌ ERROR COMÚN: Los sinohablantes tienden a ser demasiado modestos y decir «No soy muy bueno», lo que puede interpretarse como falta de confianza. Mejor di «Estoy trabajando en mejorar» o «Tengo experiencia en...».",
    "descripcionChino": "🔹 谈谈你自己：\n• 「我是一个负责任的人，容易适应团队合作」。\n• 「我有三年的客户服务经验」。\n• 「我认为自己积极主动，渴望学习」。\n• 「我喜欢解决问题并提供方案」。\n• 「我最大的优势是有效沟通」。\n\n🔹 优点和缺点：\n• 优点：「我有条理，能按时完成」\n• 优点：「我有语言天赋」\n• 缺点：「有时我过于完美主义，但我正在学习分清主次」\n• 缺点：「我很难放权，但通过实践已有所改善」\n• 建议：提到一个真实的缺点以及你如何克服它。\n\n🔹 为什么你想在这里工作？\n• 「我钦佩公司的发展历程，想为其成长贡献力量」。\n• 「我认同可持续发展和团队合作的价值观」。\n• 「我在寻找国际环境中的职业挑战」。\n• 「你们对创新的关注与我的工作方式吻合」。\n• 「我相信我能贡献我在数字营销方面的经验」。\n\n📌 重要提示：避免背诵答案；要自然并根据公司个性化。面试官看重真实性。\n\n❌ 常见错误：中文母语者往往过于谦虚，说「我不太擅长」，这可能被理解为缺乏自信。最好说「我正在努力改进」或「我在……方面有经验」。",
