    "descripcion": "🔹 LENGUAJE CORPORAL (body language):\n• Mantén una postura erguida pero relajada; evita encorvarte.\n• Sonríe de forma natural y asiente con la cabeza para mostrar interés.\n• Usa gestos moderados con las manos para acompañar tus palabras.\n• Evita cruzar los brazos; puede parecer defensivo.\n• Mantén contacto visual, pero no mires fijamente sin parpadear.\n• Controla los nervios: no juegues con el bolígrafo ni con el pelo.\n\n🔹 CORTESÍA Y TRATAMIENTO (politeness and forms of address):\n• Usa «usted» con el entrevistador hasta que te invite a tutear.\n• Saluda con un apretón de manos firme pero no demasiado fuerte.\n• Espera a que te ofrezcan asiento antes de sentarte.\n• No interrumpas; espera a que termine de hablar.\n• Agradece la oportunidad al final: «Le agradezco mucho esta entrevista».\n• Si no entiendes algo, pide amablemente: «¿Podría repetirlo, por favor?».\n\n🔹 EXPRESIONES ÚTILES (useful expressions):\n• «Encantado/a de conocerle».\n• «Es un placer estar aquí».\n• «Le agradezco su tiempo».\n• «Quedo a su disposición».\n• «Muchas gracias por la oportunidad».\n\n📌 NOTA IMPORTANTE: En culturas latinas, el espacio personal es más reducido que en Asia; no te alejes demasiado, pero respeta la distancia cómoda.\n\n❌ ERROR COMÚN: Los sinohablantes a veces evitan el contacto visual por respeto, pero en España puede interpretarse como falta de confianza o sinceridad. Es importante mirar a los ojos de forma natural.",
    "descripcionChino": "🔹 肢体语言：\n• 保持端正但放松的姿态；避免驼背。\n• 自然微笑，点头表示兴趣。\n• 适当用手势辅助表达。\n• 避免交叉双臂；可能显得防御。\n• 保持眼神交流，但不要目不转睛。\n• 控制紧张：不要玩笔或头发。\n\n🔹 礼仪与称呼：\n• 在面试官邀请你使用「你」之前，请用「您」。\n• 握手要坚定但不过于用力。\n• 等对方请你坐下再坐。\n• 不要打断；等对方说完。\n• 最后感谢机会：「Le agradezco mucho esta entrevista」。\n• 如果没听懂，礼貌请求：「¿Podría repetirlo, por favor?」。\n\n🔹 实用表达：\n• 「Encantado/a de conocerle」（很高兴认识您）。\n• 「Es un placer estar aquí」（很高兴来到这里）。\n• 「Le agradezco su tiempo」（感谢您的时间）。\n• 「Quedo a su disposición」（我随时为您效劳）。\n• 「Muchas gracias por la oportunidad」（非常感谢这个机会）。\n\n📌 重要提示：在拉美文化中，个人空间比亚洲更小；不要离得太远，但保持舒适距离。\n\n❌ 常见错误：中文母语者有时出于尊重避免眼神接触，但在西班牙可能被理解为缺乏自信或真诚。自然地注视对方很重要。",
