  "descripcion": "学习用西班牙语写正式的电子邮件和信件，掌握格式、礼貌用语和常见句型。",
  "descripcionChino": "学习用西班牙语写正式邮件和信件，掌握格式、礼貌用语和常见句型。",
  "icono": "✉️",
  "color": "#6366f1",
