    "tituloChino": "西班牙的典型菜肴",
    "descripcion": "• La paella es un plato de arroz originario de Valencia. Lleva arroz, mariscos, pollo y verduras.\n• La tortilla de patatas es un plato muy común, hecho con huevos, patatas y cebolla.\n• El gazpacho es una sopa fría de tomate, pepino, pimiento y ajo, típica del verano.\n• El jamón ibérico es un embutido curado muy famoso, se come en lonchas.\n• Las tapas son pequeñas porciones de comida que se sirven en bares.\n• Los churros con chocolate son un desayuno dulce muy popular.\n• El cocido madrileño es un guiso de garbanzos, carne y verduras.\n\n📌 NOTA IMPORTANTE: En España, la comida principal se suele tomar a las 14:00 y la cena a las 21:00 o más tarde. Las tapas se comen antes de la cena.\n❌ ERROR COMÚN: Los sinohablantes a menudo confunden \"paella\" con \"paellera\" (la sartén). La paella es el plato; la paellera es el recipiente.",
    "descripcionChino": "• 海鲜饭（paella）是源自瓦伦西亚的米饭菜肴，含有米饭、海鲜、鸡肉和蔬菜。\n• 土豆煎蛋饼（tortilla de patatas）是一道非常常见的菜，用鸡蛋、土豆和洋葱制作。\n• 西班牙冷汤（gazpacho）是一种冷汤，由番茄、黄瓜、辣椒和大蒜制成，是夏季的典型菜肴。\n• 伊比利亚火腿（jamón ibérico）是一种非常有名的腌制肉制品，切成薄片食用。\n• 小吃（tapas）是在酒吧供应的小份食物。\n• 吉事果配巧克力（churros con chocolate）是一种非常受欢迎的甜味早餐。\n• 马德里炖菜（cocido madrileño）是用鹰嘴豆、肉和蔬菜炖制的菜肴。\n\n📌 重要提示：在西班牙，主餐通常在14:00吃，晚餐在21:00或更晚。小吃通常在晚餐前吃。\n❌ 常见错误：中文母语者常把“paella”（海鲜饭）和“paellera”（海鲜饭锅）混淆。Paella是菜肴，paellera是锅。",
