    "descripcion": "• Los tacos al pastor son un plato mexicano de carne de cerdo con piña y especias, servido en tortillas.\n• La arepa es un pan de maíz típico de Venezuela y Colombia, se puede comer con queso o carne.\n• El ceviche es un plato peruano de pescado crudo marinado en limón y ají.\n• La empanada es una masa rellena de carne, queso o verduras, típica de muchos países.\n• El asado es una carne a la parrilla, muy popular en Argentina y Uruguay.\n• El mole poblano es una salsa mexicana compleja con chocolate y chiles.\n• La feijoada es un guiso de frijoles negros y carne de cerdo, típico de Brasil.\n\n📌 NOTA IMPORTANTE: En América Latina, el término \"tortilla\" puede referirse a una tortilla de maíz (plana) o a una tortilla de huevo (como en España). El contexto es clave.\n❌ ERROR COMÚN: Los sinohablantes suelen decir \"taco\" para referirse a cualquier comida mexicana, pero hay muchos platos diferentes. No todas las comidas mexicanas son tacos.",
    "descripcionChino": "• 牧师塔可（tacos al pastor）是墨西哥菜肴，用猪肉、菠萝和香料制成，放在玉米饼中食用。\n• 阿雷帕（arepa）是委内瑞拉和哥伦比亚典型的玉米饼，可以搭配奶酪或肉食用。\n• 酸橘汁腌鱼（ceviche）是秘鲁菜肴，用柠檬和辣椒腌制生鱼。\n• 恩潘纳达（empanada）是一种填充肉、奶酪或蔬菜的面团，是许多国家的典型食物。\n• 烤肉（asado）是烤架上的肉，在阿根廷和乌拉圭非常受欢迎。\n• 莫莱波布拉诺（mole poblano）是一种复杂的墨西哥酱汁，含有巧克力和辣椒。\n• 黑豆炖肉（feijoada）是用黑豆和猪肉炖制的菜肴，是巴西的典型食物。\n\n📌 重要提示：在拉丁美洲，“tortilla”一词可能指玉米饼（扁平）或鸡蛋饼（如西班牙）。语境是关键。\n❌ 常见错误：中文母语者常把“taco”当作所有墨西哥食物的代称，但墨西哥菜肴多种多样，并非都是塔可。",
