    "tituloChino": "寻找公寓：广告和关键词汇",
    "descripcion": "🔹 VOCABULARIO BÁSICO DE VIVIENDA:\n• piso = 公寓（西班牙常用）\n• apartamento = 公寓（拉美常用）\n• habitación = 房间\n• salón = 客厅\n• cocina = 厨房\n• baño = 卫生间\n• dormitorio = 卧室\n• terraza = 露台\n• balcón = 阳台\n• ascensor = 电梯\n• amueblado = 带家具的\n• sin amueblar = 不带家具的\n\n🔹 TIPOS DE ANUNCIOS:\n• se alquila = 出租\n• se vende = 出售\n• particular = 个人（非中介）\n• agencia inmobiliaria = 房地产中介\n• alquiler = 租金\n• gastos incluidos = 包含费用\n• gastos aparte = 费用另计\n• fianza = 押金\n• contrato = 合同\n• duración = 期限\n\n🔹 CARACTERÍSTICAS ÚTILES:\n• luminoso = 明亮的\n• exterior = 朝外的\n• interior = 朝内的\n• reformado = 翻新的\n• bien comunicado = 交通便利的\n• cerca del metro = 靠近地铁\n\n📌 NOTA IMPORTANTE: En España, es común que el alquiler incluya la comunidad de propietarios, pero no los suministros (agua, luz, gas). La fianza suele ser de una mensualidad.\n\n❌ ERROR COMÚN: Los sinohablantes suelen confundir 'piso' con 'suelo' (floor). 'Piso' es apartamento; 'suelo' es el suelo físico. También cuidado con 'habitación' (room) vs. 'habitáculo' (cabin).",
    "descripcionChino": "🔹 住房基本词汇：\n• piso = 公寓（西班牙常用）\n• apartamento = 公寓（拉美常用）\n• habitación = 房间\n• salón = 客厅\n• cocina = 厨房\n• baño = 卫生间\n• dormitorio = 卧室\n• terraza = 露台\n• balcón = 阳台\n• ascensor = 电梯\n• amueblado = 带家具的\n• sin amueblar = 不带家具的\n\n🔹 广告类型：\n• se alquila = 出租\n• se vende = 出售\n• particular = 个人（非中介）\n• agencia inmobiliaria = 房地产中介\n• alquiler = 租金\n• gastos incluidos = 包含费用\n• gastos aparte = 费用另计\n• fianza = 押金\n• contrato = 合同\n• duración = 期限\n\n🔹 实用特征：\n• luminoso = 明亮的\n• exterior = 朝外的\n• interior = 朝内的\n• reformado = 翻新的\n• bien comunicado = 交通便利的\n• cerca del metro = 靠近地铁\n\n📌 重要提示：在西班牙，租金通常包含物业费，但不包含水电燃气费。押金通常为一个月租金。\n\n❌ 常见错误：中文母语者常把“piso”和“suelo”（地板）混淆。“Piso”是公寓；“suelo”是地面。也要注意“habitación”（房间）和“habitáculo”（舱室）的区别。",
