  "dialogos": [
   {
    "id": "d1",
    "titulo": "Llamar por un anuncio de piso",
    "tituloChino": "打电话询问公寓广告",
    "personajes": [
     "Inquilino",
     "Casero"
    ],
    "lineas": [
     {
      "personaje": "Inquilino",
      "texto": "Buenos días, llamo por el anuncio del piso en el centro.",
      "traduccion": "早上好，我打电话问一下市中心公寓的广告。"
     },
     {
      "personaje": "Casero",
      "texto": "Sí, todavía está disponible. ¿Quiere visitarlo?",
      "traduccion": "是的，还在。您想看看吗？"
     },
     {
      "personaje": "Inquilino",
      "texto": "Sí, ¿podría ser mañana por la tarde?",
      "traduccion": "是的，明天下午可以吗？"
     },
     {
      "personaje": "Casero",
      "texto": "Perfecto. ¿A las cinco le viene bien?",
      "traduccion": "好的。五点您方便吗？"
     },
     {
      "personaje": "Inquilino",
      "texto": "Sí, me viene bien. ¿Cuánto es el alquiler?",
      "traduccion": "可以，我方便。租金是多少？"
     },
     {
      "personaje": "Casero",
      "texto": "Son 850 euros al mes, gastos de comunidad incluidos.",
      "traduccion": "每月850欧元，包含物业费。"
     },
     {
      "personaje": "Inquilino",
      "texto": "¿Y la fianza?",
      "traduccion": "押金呢？"
     },
     {
      "personaje": "Casero",
      "texto": "La fianza es de una mensualidad. ¿Le parece bien?",
      "traduccion": "押金是一个月租金。您觉得可以吗？"
     }
    ]
   },
   {
    "id": "d2",
    "titulo": "Visita al piso",
    "tituloChino": "看房",
    "personajes": [
     "Inquilino",
     "Agente"
    ],
    "lineas": [
     {
      "personaje": "Agente",
      "texto": "Este es el salón. Es exterior y muy luminoso.",
      "traduccion": "这是客厅。朝外，非常明亮。"
     },
     {
      "personaje": "Inquilino",
      "texto": "Me gusta. ¿Cuántas habitaciones hay?",
      "traduccion": "我喜欢。有几个房间？"
     },
     {
      "personaje": "Agente",
      "texto": "Hay dos habitaciones y un baño completo.",
      "traduccion": "有两个房间和一个完整卫生间。"
     },
     {
      "personaje": "Inquilino",
      "texto": "¿La cocina está equipada?",
      "traduccion": "厨房设备齐全吗？"
     },
     {
      "personaje": "Agente",
      "texto": "Sí, tiene nevera, lavadora y horno.",
      "traduccion": "是的，有冰箱、洗衣机和烤箱。"
     },
     {
      "personaje": "Inquilino",
      "texto": "¿El edificio tiene ascensor?",
      "traduccion": "楼里有电梯吗？"
     },
     {
      "personaje": "Agente",
      "texto": "Sí, y también portero automático.",
      "traduccion": "有，还有对讲机。"
     },
     {
      "personaje": "Inquilino",
      "texto": "Muy bien. ¿Se permiten mascotas?",
      "traduccion": "很好。允许养宠物吗？"
     }
    ]
   },
   {
    "id": "d3",
    "titulo": "Firmar el contrato",
    "tituloChino": "签合同",
    "personajes": [
     "Inquilino",
     "Casero"
    ],
    "lineas": [
     {
      "personaje": "Casero",
      "texto": "Aquí tiene el contrato. Léalo con calma.",
      "traduccion": "这是合同。您慢慢看。"
     },
     {
      "personaje": "Inquilino",
      "texto": "Gracias. ¿La duración es de un año?",
      "traduccion": "谢谢。期限是一年吗？"
     },
     {
      "personaje": "Casero",
      "texto": "Sí, prorrogable hasta cinco años.",
      "traduccion": "是的，可续约至五年。"
     },
     {
      "personaje": "Inquilino",
      "texto": "Entiendo. ¿La renta se actualiza cada año?",
      "traduccion": "明白。租金每年更新吗？"
     },
     {
      "personaje": "Casero",
      "texto": "Sí, según el IPC.",
      "traduccion": "是的，根据消费者物价指数。"
     },
     {
      "personaje": "Inquilino",
      "texto": "¿Y los suministros?",
      "traduccion": "水电费呢？"
     },
     {
      "personaje": "Casero",
      "texto": "Los suministros corren de su cuenta.",
      "traduccion": "水电费由您承担。"
     },
     {
      "personaje": "Inquilino",
      "texto": "De acuerdo. ¿Puedo firmar ya?",
      "traduccion": "好的。我可以现在签吗？"
     }
    ]
   },
   {
    "id": "d4",
    "titulo": "Reportar una avería",
    "tituloChino": "报告故障",
    "personajes": [
     "Inquilino",
     "Casero"
    ],
    "lineas": [
     {
      "personaje": "Inquilino",
      "texto": "Hola, le llamo porque hay un problema en el piso.",
      "traduccion": "你好，我打电话是因为公寓有问题。"
     },
     {
      "personaje": "Casero",
      "texto": "¿Qué pasa?",
      "traduccion": "怎么了？"
     },
     {
      "personaje": "Inquilino",
      "texto": "No funciona el agua caliente desde ayer.",
      "traduccion": "从昨天开始没有热水。"
     },
     {
      "personaje": "Casero",
      "texto": "Lo siento. ¿Ha revisado el termo?",
      "traduccion": "抱歉。您检查过热水器吗？"
     },
     {
      "personaje": "Inquilino",
      "texto": "Sí, pero parece que está estropeado.",
      "traduccion": "检查了，但好像坏了。"
     },
     {
      "personaje": "Casero",
      "texto": "Voy a llamar a un técnico. ¿Le va bien mañana?",
      "traduccion": "我叫个技术员。明天可以吗？"
     },
     {
      "personaje": "Inquilino",
      "texto": "Sí, por favor. ¿Quién paga la reparación?",
      "traduccion": "好的，拜托。谁付维修费？"
     },
     {
      "personaje": "Casero",
      "texto": "Corre de mi cuenta, no se preocupe.",
      "traduccion": "我付，别担心。"
     }
    ]
   }
  ],
