   {
    "id": "t4",
    "titulo": "Preguntar y expresar emociones en diálogo",
    "tituloChino": "在对话中询问和表达情绪",
    "descripcion": "Para preguntar sobre emociones usamos:\n• ¿Cómo estás? = How are you?\n• ¿Cómo te sientes? = How do you feel?\n• ¿Qué te pasa? = What's wrong? / What's the matter?\n• ¿Estás bien? = Are you okay?\n\nPara responder:\n• Estoy + adjetivo: Estoy contento.\n• Tengo + sustantivo: Tengo miedo.\n• Me siento + adjetivo: Me siento triste.\n\n📌 NOTA IMPORTANTE: La expresión ¿Qué te pasa? es muy común para preguntar por qué alguien está mal. Se responde con porque: Estoy triste porque mi perro está enfermo.\n\n❌ ERROR COMÚN: No confundas ¿Cómo estás? (estado general) con ¿Cómo eres? (descripción de personalidad). Para emociones usa siempre ESTAR.",
    "descripcionChino": "询问情绪常用：\n• ¿Cómo estás? = 你好吗？\n• ¿Cómo te sientes? = 你感觉怎么样？\n• ¿Qué te pasa? = 你怎么了？\n• ¿Estás bien? = 你没事吧？\n\n回答：\n• Estoy + 形容词：Estoy contento. 我很高兴。\n• Tengo + 名词：Tengo miedo. 我害怕。\n• Me siento + 形容词：Me siento triste. 我感到难过。\n\n📌 重要提示：¿Qué te pasa? 非常常用，询问为什么状态不好。用porque回答：Estoy triste porque mi perro está enfermo. 我难过是因为我的狗病了。\n\n❌ 常见错误：不要混淆 ¿Cómo estás?（一般状态）和 ¿Cómo eres?（性格描述）。表达情绪总是用ESTAR。",
    "ejemplos": [
     {
      "espanol": "¿Cómo estás hoy? — Estoy un poco cansado.",
      "chino": "你今天怎么样？——我有点累。"
     },
     {
      "espanol": "¿Qué te pasa? — Tengo miedo de la oscuridad.",
      "chino": "你怎么了？——我害怕黑暗。"
     },
     {
      "espanol": "¿Cómo te sientes después de la noticia?",
      "chino": "听到消息后你感觉怎么样？"
     },
     {
      "espanol": "Estoy preocupado porque mi hijo está enfermo.",
      "chino": "我担心因为我儿子病了。"
     },
     {
      "espanol": "Me siento muy feliz cuando estoy con mis amigos.",
      "chino": "和朋友在一起时我感到很开心。"
     }
    ]
   }
