    "lineas": [
     {
      "personaje": "Elena García",
      "texto": "Buenos días, ¿puedo echar un vistazo a sus productos?",
      "traduccion": "早上好，我可以看看你们的产品吗？"
     },
     {
      "personaje": "Wang Lei",
      "texto": "Por supuesto. Le presento nuestro nuevo modelo de panel solar.",
      "traduccion": "当然。我向您介绍我们新款太阳能板。"
     },
     {
      "personaje": "Elena García",
      "texto": "Muy interesante. ¿Qué eficiencia tiene?",
      "traduccion": "很有意思。它的效率如何？"
     },
     {
      "personaje": "Wang Lei",
      "texto": "Tiene una eficiencia del veintidós por ciento, líder en el mercado.",
      "traduccion": "效率达到百分之二十二，市场领先。"
     },
     {
      "personaje": "Elena García",
      "texto": "¿Y cuál es el precio unitario?",
      "traduccion": "单价是多少？"
     },
     {
      "personaje": "Wang Lei",
      "texto": "Depende de la cantidad. Para pedidos grandes, es muy competitivo.",
      "traduccion": "取决于数量。对于大订单，非常有竞争力。"
     },
     {
      "personaje": "Elena García",
      "texto": "Le agradecería que me enviara una cotización formal.",
      "traduccion": "如蒙发送正式报价，我将不胜感激。"
     },
     {
      "personaje": "Wang Lei",
      "texto": "Con mucho gusto. ¿Me deja su tarjeta de visita?",
      "traduccion": "很乐意。您能给我您的名片吗？"
     }
    ]
