  "descripcion": "学习用西班牙语讨论科学发现、技术发展和创新趋势，提升在科技领域的表达能力。",
  "descripcionChino": "学习用西班牙语讨论科学发现、技术发展和创新趋势，提升科技领域的表达能力。",
  "icono": "🔬",
