   {
    "id": "t3",
    "titulo": "Las vanguardias y la Generación del 27",
    "tituloChino": "先锋派与27年一代",
    "descripcion": "A principios del siglo XX, las vanguardias europeas (futurismo, cubismo, surrealismo) llegan a España. En literatura, la Generación del 27 (Lorca, Alberti, Cernuda, Salinas, Guillén, Aleixandre, etc.) combina tradición y vanguardia. Lorca destaca por su poesía y teatro (Bodas de sangre, La casa de Bernarda Alba). En arte, Picasso, Dalí y Miró son figuras clave del surrealismo y el cubismo. La Guerra Civil (1936-1939) marca un antes y un después; muchos artistas se exilian.\n• La Generación del 27 mezcla lo popular y lo culto.\n• Lorca es el poeta y dramaturgo más universal.\n• El surrealismo influye en Dalí y Buñuel.\n• Picasso revoluciona la pintura con el cubismo.\n• El exilio republicano enriquece la cultura de otros países.\n\n📌 NOTA IMPORTANTE: La Generación del 27 no es un grupo homogéneo; sus miembros tienen estilos diversos, pero comparten el homenaje a Góngora en 1927. El surrealismo español tiene un carácter muy personal.\n\n❌ ERROR COMÚN: Los estudiantes chinos suelen pensar que todos los artistas de la época son surrealistas; en realidad, hay una mezcla de movimientos. También confunden a Lorca con un poeta solo rural, cuando su obra es muy variada y cosmopolita.",
    "descripcionChino": "20世纪初，欧洲先锋派（未来主义、立体主义、超现实主义）传入西班牙。文学上，27年一代（洛尔迦、阿尔贝蒂、塞尔努达、萨利纳斯、纪廉、阿莱克桑德雷等）将传统与先锋结合。洛尔迦以诗歌和戏剧著称（《血婚》《贝尔纳达·阿尔巴之家》）。艺术上，毕加索、达利和米罗是超现实主义和立体主义的关键人物。西班牙内战（1936-1939）划出分水岭；许多艺术家流亡。\n• 27年一代融合通俗与高雅。\n• 洛尔迦是最具世界性的诗人和剧作家。\n• 超现实主义影响达利和布努埃尔。\n• 毕加索以立体主义革新绘画。\n• 共和派流亡丰富了其他国家的文化。\n\n📌 重要提示：27年一代并非同质群体；成员风格多样，但共同参与1927年纪念贡戈拉的活动。西班牙超现实主义具有鲜明的个人特色。\n\n❌ 常见错误：中国学生常认为那个时期所有艺术家都是超现实主义者；实际上多种运动并存。他们还把洛尔迦误认为只是乡村诗人，而他的作品非常多样且国际化。",
    "ejemplos": [
     {
      "espanol": "Lorca escribió 'Bodas de sangre' en 1933.",
      "chino": "洛尔迦于1933年写了《血婚》。"
     },
     {
      "espanol": "Dalí y Buñuel colaboraron en 'Un perro andaluz'.",
      "chino": "达利和布努埃尔合作了《一条安达鲁狗》。"
     },
     {
      "espanol": "La Generación del 27 homenajeó a Góngora.",
      "chino": "27年一代向贡戈拉致敬。"
     },
     {
      "espanol": "Picasso pintó el 'Guernica' en 1937.",
      "chino": "毕加索于1937年画了《格尔尼卡》。"
     },
     {
      "espanol": "El surrealismo busca liberar el inconsciente.",
      "chino": "超现实主义试图解放潜意识。"
     }
    ]
   },
   {
    "id": "t4",
    "titulo": "La literatura hispanoamericana: del modernismo al boom",
    "tituloChino": "西班牙语美洲文学：从现代主义到文学爆炸",
    "descripcion": "La literatura hispanoamericana ha tenido un impacto global. El modernismo, liderado por Rubén Darío, renueva la poesía en español. En el siglo XX, destacan Jorge Luis Borges (cuentos fantásticos), Pablo Neruda (poesía amorosa y política), Gabriel García Márquez (Cien años de soledad, realismo mágico), Julio Cortázar (Rayuela), Mario Vargas Llosa y Carlos Fuentes. El 'boom' de los años 60 y 70 proyecta esta literatura internacionalmente. En arte, el muralismo mexicano (Rivera, Orozco, Siqueiros) y la arquitectura de Barragán son aportes importantes.\n• El modernismo renueva el lenguaje poético.\n• Borges juega con la metaficción y la eternidad.\n• García Márquez es el Nobel del realismo mágico.\n• Cortázar innova con 'Rayuela' y su estructura abierta.\n• El muralismo mexicano tiene un fuerte compromiso social.\n\n📌 NOTA IMPORTANTE: El término 'boom' se refiere a un fenómeno editorial, no a un movimiento homogéneo. Muchos autores del boom vivieron en Europa y fueron influidos por las vanguardias.\n\n❌ ERROR COMÚN: Los estudiantes chinos a menudo reducen la literatura hispanoamericana al realismo mágico, pero hay mucha variedad: poesía, ensayo, cuento fantástico. También confunden a Borges con un novelista, cuando es principalmente cuentista y ensayista.",
    "descripcionChino": "西班牙语美洲文学具有全球影响。现代主义以鲁文·达里奥为首，革新了西班牙语诗歌。20世纪，豪尔赫·路易斯·博尔赫斯（奇幻短篇）、巴勃罗·聂鲁达（爱情和政治诗歌）、加夫列尔·加西亚·马尔克斯（《百年孤独》，魔幻现实主义）、胡利奥·科塔萨尔（《跳房子》）、马里奥·巴尔加斯·略萨和卡洛斯·富恩特斯等脱颖而出。60和70年代的“文学爆炸”使这一文学国际化。艺术上，墨西哥壁画运动（里维拉、奥罗斯科、西凯罗斯）和巴拉甘的建筑是重要贡献。\n• 现代主义革新诗歌语言。\n• 博尔赫斯玩弄元小说和永恒。\n• 加西亚·马尔克斯是魔幻现实主义的诺贝尔奖得主。\n• 科塔萨尔以《跳房子》及其开放结构创新。\n• 墨西哥壁画运动具有强烈的社会责任感。\n\n📌 重要提示：“boom”一词指出版现象，而非同质运动。许多爆炸作家旅居欧洲，受先锋派影响。\n\n❌ 常见错误：中国学生常将西班牙语美洲文学简化为魔幻现实主义，但实际上种类繁多：诗歌、散文、奇幻短篇。他们还误以为博尔赫斯是小说家，而他主要是短篇小说家和散文家。",
    "ejemplos": [
     {
      "espanol": "Rubén Darío inició el modernismo con 'Azul'.",
      "chino": "鲁文·达里奥以《蓝》开创现代主义。"
     },
     {
      "espanol": "García Márquez ganó el Nobel en 1982.",
      "chino": "加西亚·马尔克斯于1982年获诺贝尔奖。"
     },
     {
      "espanol": "Borges escribió 'El Aleph' y 'Ficciones'.",
      "chino": "博尔赫斯写了《阿莱夫》和《虚构集》。"
     },
     {
      "espanol": "Cortázar propone una lectura activa en 'Rayuela'.",
      "chino": "科塔萨尔在《跳房子》中提出主动阅读。"
     },
     {
      "espanol": "Rivera pintó murales sobre la historia de México.",
      "chino": "里维拉画了关于墨西哥历史的壁画。"
     }
    ]
   }
