   {
    "id": "d4",
    "titulo": "En una exposición de arte contemporáneo",
    "tituloChino": "在当代艺术展",
    "personajes": [
     "Amiga",
     "Amigo"
    ],
    "lineas": [
     {
      "personaje": "Amiga",
      "texto": "¿Has visto la obra de Picasso en esta sala?",
      "traduccion": "你看到这个展厅里毕加索的作品了吗？"
     },
     {
      "personaje": "Amigo",
      "texto": "Sí, el cuadro cubista me parece revolucionario.",
      "traduccion": "看到了，那幅立体主义画作我觉得很革命性。"
     },
     {
      "personaje": "Amiga",
      "texto": "A mí me impresiona más Dalí, con sus relojes blandos.",
      "traduccion": "达利更让我印象深刻，那些软表。"
     },
     {
      "personaje": "Amigo",
      "texto": "Dalí es surrealista, juega con el inconsciente.",
      "traduccion": "达利是超现实主义者，玩弄潜意识。"
     },
     {
      "personaje": "Amiga",
      "texto": "¿Y qué opinas de Miró?",
      "traduccion": "你觉得米罗怎么样？"
     },
     {
      "personaje": "Amigo",
      "texto": "Su arte es más abstracto y lúdico, como un sueño infantil.",
      "traduccion": "他的艺术更抽象、更富有童趣，像童年的梦。"
     },
     {
      "personaje": "Amiga",
      "texto": "Me gusta cómo combinan elementos oníricos y políticos.",
      "traduccion": "我喜欢他们如何结合梦境和政治元素。"
     },
     {
      "personaje": "Amigo",
      "texto": "Sí, el arte de vanguardia refleja la crisis de su época.",
      "traduccion": "是的，先锋艺术反映了他们时代的危机。"
     }
    ]
   }
