  "titulo": "Conectores del Discurso - Escribir Mejor",
  "tituloChino": "语篇连接词 - 写得更好",
  "descripcion": "学习使用西班牙语语篇连接词，使写作和口语表达更连贯、更有逻辑。",
  "descripcionChino": "学习使用西班牙语语篇连接词，使写作和口语表达更连贯、更有逻辑。",
  "icono": "🔗",
