    "respuestaSugerida": "'Para siempre' significa 'forever' (para el futuro). 'Por siempre' también significa 'forever' pero es más literario o enfático.",
    "respuestaSugeridaChino": "'para siempre'意思是'永远'（面向未来）。'por siempre'也意思是'永远'，但更文学化或强调。"
