  "titulo": "La voz pasiva y el se impersonal",
  "tituloChino": "被动语态与无人称句 se",
  "descripcion": "学习西班牙语被动语态的结构和用法，掌握无人称句 se 的构成和常见场景。",
  "descripcionChino": "学习西班牙语被动语态的结构和用法，掌握无人称句 se 的构成和常见场景。",
  "icono": "🔄",
