    "titulo": "Comprensión de lectura",
    "tituloChino": "阅读理解",
    "descripcion": "La prueba de comprensión de lectura del DELE B2 consta de 4 tareas y 36 preguntas. Tienes 70 minutos para completarla. Estrategias clave:\n• Lee primero las preguntas, no el texto completo. Así sabrás qué información buscar.\n• Identifica palabras clave en las preguntas y búscalas en el texto.\n• No te detengas en palabras desconocidas; deduce su significado por el contexto.\n• Gestiona el tiempo: no dediques más de 15-20 minutos por tarea.\n• En las preguntas de verdadero/falso, localiza la evidencia en el texto antes de responder.\n• Para las tareas de emparejamiento, lee todas las opciones antes de decidir.\n• Revisa tus respuestas al final, pero no cambies sin una razón clara.\n\n📌 NOTA IMPORTANTE: La prueba de lectura es la primera del examen. Mantén la calma y empieza por la tarea que te resulte más fácil para ganar confianza.\n\n❌ ERROR COMÚN: Muchos estudiantes leen el texto palabra por palabra y se quedan sin tiempo. Los sinohablantes tienden a traducir mentalmente todo al chino, lo que ralentiza la lectura. Practica la lectura directa en español y evita la traducción literal.",
    "descripcionChino": "DELE B2阅读理解考试包含4个任务和36道题，考试时间70分钟。关键策略：\n• 先读题目，不要先读全文，这样你就知道要寻找什么信息。\n• 找出题目中的关键词，并在文中定位。\n• 不要纠结于生词，通过上下文推断词义。\n• 管理好时间：每个任务不超过15-20分钟。\n• 在判断题中，先在文中找到证据再作答。\n• 对于配对题，先阅读所有选项再做决定。\n• 最后检查答案，但不要没有明确理由就改动。\n\n📌 重要提示：阅读考试是考试的第一部分。保持冷静，从你最有把握的任务开始，以建立信心。\n\n❌ 常见错误：许多学生逐字阅读，导致时间不够。中文母语者倾向于在脑中把一切翻译成中文，这减慢了阅读速度。练习直接阅读西班牙语，避免字面翻译。",
